<script setup lang="ts">import {computed} from 'vue';import type {Snapshot,Run,Finding,Plan} from '../types/domain';import PageTitle from '../components/common/PageTitle.vue';import HistogramBins from '../components/HistogramBins.vue';import FindingSummary from '../components/FindingSummary.vue';import RunTable from '../components/RunTable.vue';import Empty from '../components/common/Empty.vue';const props=defineProps<{snapshots:Snapshot[];runs:Run[];findings:Finding[];plans:Plan[];features:Record<string,string>}>();defineEmits<{select:[run:Run]}>();const run=computed(()=>props.runs.find(r=>r.status==='succeeded')),findings=computed(()=>props.findings.filter(f=>f.run_id===run.value?.id)),focus=computed(()=>findings.value.find(f=>f.feature==='duration')||findings.value[0]);</script><template><PageTitle index="01 / EDITORIAL" title="变化先核对，结论慢一点。" description="冻结参考箱，将新增语料投到同一把标尺上。差异大小、统计证据与补采说明，分别读清楚。"><a class="button primary" href="#compare">建立比较校样 ↗</a></PageTitle><div class="editorial-grid"><section class="proof-feature"><header><small>LATEST PROOF / 最近完成</small><span>参考冻结 · 候选投影</span></header><h2>{{run?.name||'等待第一份校样'}}</h2><template v-if="focus"><div class="feature-caption"><b>{{features[focus.feature]}}</b><small>{{run?.result.reference_n}} 参考片段 / {{run?.result.candidate_n}} 候选片段</small></div><HistogramBins :finding="focus"/><FindingSummary :finding="focus"/><button class="text-button" @click="$emit('select',run!)">阅读完整发现与FDR依据 →</button></template><Empty v-else title="暂无分布校样" help="先确认参考与候选快照，再提交比较。"/></section><aside class="editorial-column"><small>SOURCE DESK / 来源备忘</small><div class="source-number" v-for="s in snapshots" :key="s.id"><span>{{s.kind==='reference'?'参考训练快照':'候选新增快照'}}</span><b>{{s.count.toLocaleString()}}</b><small>{{s.filename}}</small></div><dl><dt>本次特征</dt><dd>{{findings.length}}</dd><dt>建议人工核对</dt><dd>{{findings.filter(f=>f.status==='review').length}}</dd><dt>已确认补采计划</dt><dd>{{plans.filter(p=>p.status==='approved').length}}</dd></dl><blockquote>漂移发生了，<br/>模型未必变差。<p>分布证据帮助定位采集变化；质量判断需要独立下游评测。</p></blockquote></aside></div><div class="section-title"><h2>校样索引</h2><small>每次比较保留参数、冻结箱与输入指纹</small></div><RunTable :runs="runs.slice(0,5)" @select="$emit('select',$event)"/></template>
